    vector<vector<int>> pref(n + 1, vector<int>(m + 1, 0));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            pref[i + 1][j + 1] = pref[i][j + 1] + pref[i + 1][j] - pref[i][j] + (grid[i][j] == 'g' ? 1 : 0);
        }
    }
    auto gold_sum = [&](int r1, int c1, int r2, int c2) {
        if (r1 > r2 || c1 > c2) return 0;
        r1 = max(0, r1); c1 = max(0, c1);
        r2 = min(n - 1, r2); c2 = min(m - 1, c2);
        if (r1 > r2 || c1 > c2) return 0;
        return pref[r2 + 1][c2 + 1] - pref[r1][c2 + 1] - pref[r2 + 1][c1] + pref[r1][c1];
    };

    // prefix sum of empty cells
    vector<vector<int>> empty_pref(n + 1, vector<int>(m + 1, 0));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            empty_pref[i + 1][j + 1] = empty_pref[i][j + 1] + empty_pref[i + 1][j] - empty_pref[i][j] + (grid[i][j] == '.' ? 1 : 0);
        }
    }
