        if (r1 > r2 || c1 > c2) return 0;
        r1 = max(0, r1); c1 = max(0, c1);
        r2 = min(n - 1, r2); c2 = min(m - 1, c2);
        if (r1 > r2 || c1 > c2) return 0;
        return empty_pref[r2 + 1][c2 + 1] - empty_pref[r1][c2 + 1] - empty_pref[r2 + 1][c1] + empty_pref[r1][c1];
